'use client'

import { useEffect, useState } from 'react'
import { useAppKit, useAppKitAccount, useAppKitProvider } from '@reown/appkit/react'
import { BrowserProvider, Contract, formatEther, parseEther, ethers } from 'ethers'
import { CONFIG } from '@/config'
import Link from 'next/link'

export default function Home() {
  const { open } = useAppKit()
  const { address, isConnected } = useAppKitAccount()
  const { walletProvider } = useAppKitProvider('eip155')

  const [balanceA, setBalanceA] = useState('0.00')
  const [balanceB, setBalanceB] = useState('0.00')
  const [liquidityA, setLiquidityA] = useState('0')
  const [liquidityB, setLiquidityB] = useState('0')
  const [nonceA, setNonceA] = useState('0')
  const [nonceB, setNonceB] = useState('0')

  const [amount, setAmount] = useState('')
  const [priorityFee, setPriorityFee] = useState('0.001')
  const [direction, setDirection] = useState('A→B')
  const [status, setStatus] = useState({ type: '', message: '' })
  const [loading, setLoading] = useState(false)

  // Contracts
  const [evvmA, setEvvmA] = useState<Contract | null>(null)
  const [evvmB, setEvvmB] = useState<Contract | null>(null)
  const [balancer, setBalancer] = useState<Contract | null>(null)

  // Cache para balances
  const [balanceCache, setBalanceCache] = useState({
    A: { value: '0', timestamp: 0 },
    B: { value: '0', timestamp: 0 }
  })
  const CACHE_TTL = 5000 // 5 segundos

  useEffect(() => {
    if (isConnected && walletProvider && address) {
      initContracts()
    }
  }, [isConnected, walletProvider, address])

  const initContracts = async () => {
    if (!walletProvider) return

    try {
      const provider = new BrowserProvider(walletProvider as any)
      const signer = await provider.getSigner()

      const evvmAContract = new Contract(
        CONFIG.EVVM_A.address,
        CONFIG.ABI.EVVM,
        signer
      )

      const evvmBContract = new Contract(
        CONFIG.EVVM_B.address,
        CONFIG.ABI.EVVM,
        signer
      )

      const balancerContract = new Contract(
        CONFIG.BALANCER.address,
        CONFIG.ABI.BALANCER,
        signer
      )

      setEvvmA(evvmAContract)
      setEvvmB(evvmBContract)
      setBalancer(balancerContract)

      // Cargar datos en paralelo
      await Promise.all([
        refreshBalances(evvmAContract, evvmBContract),
        loadStats(balancerContract)
      ])

    } catch (error) {
      console.error('Contract init error:', error)
      showStatus('error', '❌ Failed to initialize contracts')
    }
  }

  const refreshBalances = async (contractA?: Contract, contractB?: Contract) => {
    if (!address) {
      console.log('No address connected')
      return
    }

    const evvmAContract = contractA || evvmA
    const evvmBContract = contractB || evvmB

    if (!evvmAContract || !evvmBContract) {
      console.log('Contracts not initialized')
      return
    }

    try {
      const now = Date.now()
      const balancesPromises = []

      console.log('Fetching balances for:', address)
      console.log('EVVM-A:', CONFIG.EVVM_A.address)
      console.log('EVVM-B:', CONFIG.EVVM_B.address)
      console.log('Principal Token:', CONFIG.EVVM_A.principalToken)

      // Check cache for EVVM-A
      if (now - balanceCache.A.timestamp > CACHE_TTL) {
        balancesPromises.push(
          evvmAContract.getBalance(address, CONFIG.EVVM_A.principalToken)
            .then((bal: any) => {
              console.log('Balance A (raw):', bal.toString())
              const formatted = parseFloat(formatEther(bal)).toFixed(4)
              console.log('Balance A (formatted):', formatted)
              setBalanceCache(prev => ({
                ...prev,
                A: { value: formatted, timestamp: now }
              }))
              return formatted
            })
            .catch((err: any) => {
              console.error('Error fetching balance A:', err)
              throw err
            })
        )
      } else {
        balancesPromises.push(Promise.resolve(balanceCache.A.value))
      }

      // Check cache for EVVM-B
      if (now - balanceCache.B.timestamp > CACHE_TTL) {
        balancesPromises.push(
          evvmBContract.getBalance(address, CONFIG.EVVM_B.principalToken)
            .then((bal: any) => {
              console.log('Balance B (raw):', bal.toString())
              const formatted = parseFloat(formatEther(bal)).toFixed(4)
              console.log('Balance B (formatted):', formatted)
              setBalanceCache(prev => ({
                ...prev,
                B: { value: formatted, timestamp: now }
              }))
              return formatted
            })
            .catch((err: any) => {
              console.error('Error fetching balance B:', err)
              throw err
            })
        )
      } else {
        balancesPromises.push(Promise.resolve(balanceCache.B.value))
      }

      const [balA, balB] = await Promise.all(balancesPromises)
      setBalanceA(balA)
      setBalanceB(balB)

    } catch (error: any) {
      console.error('Error refreshing balances:', error)
      console.error('Error details:', error.message)
      setBalanceA('Error')
      setBalanceB('Error')
      showStatus('error', `❌ Error loading balances: ${error.message}`)
    }
  }

  const loadStats = async (balancerContract?: Contract) => {
    if (!address) return

    const contract = balancerContract || balancer
    if (!contract) return

    try {
      const [liquidity, nA, nB] = await Promise.all([
        contract.getTotalLiquidity(),
        contract.noncesA(address),
        contract.noncesB(address)
      ])

      setLiquidityA(parseFloat(formatEther(liquidity.inA)).toFixed(2))
      setLiquidityB(parseFloat(formatEther(liquidity.inB)).toFixed(2))
      setNonceA(nA.toString())
      setNonceB(nB.toString())

    } catch (error) {
      console.error('Error loading stats:', error)
    }
  }

  const initiateTransfer = async () => {
    if (!isConnected) {
      open()
      return
    }

    if (!amount || parseFloat(amount) <= 0) {
      showStatus('error', '❌ Please enter valid amount')
      return
    }

    if (!priorityFee || parseFloat(priorityFee) < 0.001) {
      showStatus('error', '❌ Priority fee must be at least 0.001 ETH')
      return
    }

    if (!balancer || !address || !walletProvider) return

    try {
      setLoading(true)
      showStatus('info', '🔄 Preparing transfer...')

      const provider = new BrowserProvider(walletProvider as any)
      const signer = await provider.getSigner()

      const amountWei = parseEther(amount)
      const priorityFeeWei = parseEther(priorityFee)

      // Get nonce and EVVM config
      let nonce, evvmContract, evvmAddress, principalToken, evvmID
      if (direction === 'A→B') {
        nonce = await balancer.noncesA(address)
        evvmContract = evvmA
        evvmAddress = CONFIG.EVVM_A.address
        principalToken = CONFIG.EVVM_A.principalToken
        evvmID = '0' // EVVM-A ID
      } else {
        nonce = await balancer.noncesB(address)
        evvmContract = evvmB
        evvmAddress = CONFIG.EVVM_B.address
        principalToken = CONFIG.EVVM_B.principalToken
        evvmID = '0' // EVVM-B ID
      }

      // EVVM uses a specific format for pay() signatures:
      // "{evvmID},pay,{receiverAddress},{token},{amount},{priorityFee},{nonce},{priorityFlag},{executor}"
      // Where priorityFlag=true for async nonce
      //
      // CRITICAL FIX: The Balancer passes msg.sender (fisher) as executor to EVVM.pay()
      // But we don't know who the fisher will be when signing.
      // Solution: Use address(0) as executor, which bypasses executor verification in EVVM
      // (See Evvm.sol line 375: "if (executor != address(0)) { ... }")
      const message = `${evvmID},pay,${CONFIG.BALANCER.address.toLowerCase()},${principalToken.toLowerCase()},${amountWei.toString()},${priorityFeeWei.toString()},${nonce.toString()},true,0x0000000000000000000000000000000000000000`

      console.log('🔐 Signing message:', message)

      showStatus('info', '✍️ Please sign the message in your wallet...')

      // Sign message using personal_sign (EIP-191)
      const signature = await signer.signMessage(message)

      // Verify signature immediately to catch MetaMask/ethers.js discrepancies
      try {
        const recoveredAddress = ethers.verifyMessage(message, signature)
        console.log('🔍 Signature verification:')
        console.log('  Original address:', address)
        console.log('  Recovered address:', recoveredAddress)
        console.log('  Match:', recoveredAddress.toLowerCase() === address.toLowerCase())

        if (recoveredAddress.toLowerCase() !== address.toLowerCase()) {
          throw new Error(`Signature verification failed: expected ${address}, got ${recoveredAddress}`)
        }
      } catch (verifyError) {
        console.error('❌ Signature verification failed:', verifyError)
        showStatus('error', '❌ Signature verification failed. Please try again.')
        return
      }

      // Save pending transfer
      const transfer = {
        user: address.toLowerCase(), // Normalize to lowercase for consistency
        amount: amount,
        direction: direction,
        nonce: nonce.toString(),
        priorityFee: priorityFee,
        signature: signature,
        timestamp: Date.now()
      }

      const pending = JSON.parse(localStorage.getItem('pendingTransfers') || '[]')
      pending.push(transfer)
      localStorage.setItem('pendingTransfers', JSON.stringify(pending))

      showStatus('success', '✅ Transfer signed! Fisher will execute it soon.')

      setAmount('')

      setTimeout(() => {
        refreshBalances()
        loadStats()
      }, 2000)

    } catch (error: any) {
      console.error('Transfer error:', error)
      showStatus('error', `❌ Transfer failed: ${error.message}`)
    } finally {
      setLoading(false)
    }
  }

  const showStatus = (type: string, message: string) => {
    setStatus({ type, message })

    if (type === 'success' || type === 'error') {
      setTimeout(() => {
        setStatus({ type: '', message: '' })
      }, 5000)
    }
  }

  const requestFaucet = async (evvmType: 'A' | 'B') => {
    if (!address || !walletProvider) return

    const contract = evvmType === 'A' ? evvmA : evvmB
    if (!contract) return

    try {
      setLoading(true)
      showStatus('info', '🚰 Requesting MATE tokens from faucet...')

      const provider = new BrowserProvider(walletProvider as any)
      const signer = await provider.getSigner()

      const contractWithSigner = contract.connect(signer) as any

      // Request 100 MATE tokens
      const amount = parseEther('100')
      const tx = await contractWithSigner.addBalance(
        address,
        evvmType === 'A' ? CONFIG.EVVM_A.principalToken : CONFIG.EVVM_B.principalToken,
        amount
      )

      showStatus('info', '⏳ Waiting for transaction confirmation...')
      await tx.wait()

      showStatus('success', '✅ 100 MATE tokens added!')

      setTimeout(() => {
        refreshBalances()
      }, 1000)

    } catch (error: any) {
      console.error('Faucet error:', error)
      showStatus('error', `❌ Faucet failed: ${error.message}`)
    } finally {
      setLoading(false)
    }
  }

  return (
    <div className="container">
      {/* Header */}
      <div className="header">
        <h1>🔄 EVVM Cross-Chain Balancer</h1>
        <p className="subtitle">Transfer MATE tokens between EVVM-A and EVVM-B on the same host chain</p>

        <div style={{ display: 'flex', gap: '10px', marginTop: '15px', alignItems: 'center', flexWrap: 'wrap' }}>
          {isConnected && address ? (
            <div className="connected-wallet">
              Connected: {address.substring(0, 6)}...{address.substring(38)}
            </div>
          ) : (
            <button onClick={() => open()} className="connect-btn">
              🔗 Connect Wallet
            </button>
          )}

          <Link href="/fisher">
            <button style={{ maxWidth: '200px' }}>
              🎣 Fisher Dashboard
            </button>
          </Link>
        </div>
      </div>

      {/* Main Cards */}
      <div className="cards">
        {/* EVVM-A Balance */}
        <div className="card">
          <h2>📍 EVVM-A</h2>
          <div className="balance-box">
            <div className="balance-label">Your Balance</div>
            <div className="balance-amount">{balanceA}</div>
            <div className="balance-token">MATE</div>
          </div>
          <button onClick={() => refreshBalances()} style={{ marginBottom: '10px' }}>🔄 Refresh</button>
          <button onClick={() => requestFaucet('A')} disabled={loading}>🚰 Get 100 MATE</button>
        </div>

        {/* Transfer Section */}
        <div className="card">
          <h2>💸 Transfer</h2>

          <select value={direction} onChange={(e) => setDirection(e.target.value)}>
            <option value="A→B">Transfer A → B</option>
            <option value="B→A">Transfer B → A</option>
          </select>

          <input
            type="number"
            value={amount}
            onChange={(e) => setAmount(e.target.value)}
            placeholder="Amount to transfer"
            step="0.01"
          />

          <input
            type="number"
            value={priorityFee}
            onChange={(e) => setPriorityFee(e.target.value)}
            placeholder="Priority Fee (min 0.001 ETH)"
            step="0.001"
          />

          <button onClick={initiateTransfer} disabled={loading}>
            🚀 Initiate Transfer
          </button>

          <div className="fee-info">
            Fisher Fee: 0.1% • Priority Fee: Customizable
          </div>

          {status.message && (
            <div className={`status ${status.type}`}>
              {status.message}
            </div>
          )}
        </div>

        {/* EVVM-B Balance */}
        <div className="card">
          <h2>📍 EVVM-B</h2>
          <div className="balance-box">
            <div className="balance-label">Your Balance</div>
            <div className="balance-amount">{balanceB}</div>
            <div className="balance-token">MATE</div>
          </div>
          <button onClick={() => refreshBalances()} style={{ marginBottom: '10px' }}>🔄 Refresh</button>
          <button onClick={() => requestFaucet('B')} disabled={loading}>🚰 Get 100 MATE</button>
        </div>
      </div>

      {/* Stats Section */}
      <div className="card">
        <h2>📊 Balancer Stats</h2>
        <div className="stats-grid">
          <div className="stat">
            <div className="stat-label">Total Liquidity A</div>
            <div className="stat-value">{liquidityA}</div>
          </div>
          <div className="stat">
            <div className="stat-label">Total Liquidity B</div>
            <div className="stat-value">{liquidityB}</div>
          </div>
          <div className="stat">
            <div className="stat-label">Your Nonce A</div>
            <div className="stat-value">{nonceA}</div>
          </div>
          <div className="stat">
            <div className="stat-label">Your Nonce B</div>
            <div className="stat-value">{nonceB}</div>
          </div>
        </div>
      </div>
    </div>
  )
}
